<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import{onMount}from'svelte';
  import type{DesignSnapshot,DesignOperation,InscriptionElement}from'@schubert/contracts';
  import{parseMillimetres,measureValue,D}from'@schubert/geometry';
  let{inscription,snapshot,glyphs=[],evidence=[],onsubmit,onclose}:{inscription:InscriptionElement;snapshot:DesignSnapshot;glyphs?:any[];evidence?:any[];onsubmit:(operations:DesignOperation[])=>void;onclose:()=>void}=$props();
  let dialog:HTMLDialogElement,entries:Array<{assetId:string;u:string;v:string}>=$state([]),error=$state(''),evidenceId=$state('');
  const available=$derived(glyphs.filter(g=>g.font_variant_id===inscription.fontVariantVersionId&&g.approved_at&&g.rights_verified&&g.geometry_verified&&g.contour));
  const requested=$derived(measureValue(snapshot,inscription.requestedHeightMeasureId));
  onMount(()=>{entries=inscription.glyphPlacements.map(p=>({assetId:p.glyphAssetVersionId,u:p.uMm,v:p.vMm}));dialog.showModal();return()=>dialog.close();});
  function commit(event:SubmitEvent){event.preventDefault();error='';try{
    const selected=entries.map(entry=>{const asset=available.find(g=>g.id===entry.assetId),u=parseMillimetres(entry.u),v=parseMillimetres(entry.v);if(!asset||u===null||v===null)throw new Error('Für jede Position ein freigegebenes Original und die belegten u/v-Werte eingeben.');if(!requested||!asset.nominal_font_height_mm||!new D(requested).eq(asset.nominal_font_height_mm))throw new Error('Hersteller-Nennschrifthöhe des Originals passt nicht zur gewünschten Ausführung. Keine automatische Skalierung.');return{entry,asset,u,v};});
    if(!selected.length||selected.map(p=>p.asset.text).join('').replace(/\s/g,'')!==inscription.exactText.replace(/\s/g,''))throw new Error('Die Originalzeichen müssen den wörtlichen Text in dieser Reihenfolge vollständig abdecken. Leerzeichen und Zeilenpositionen bleiben ausdrücklich im Wortlaut und in u/v erhalten.');
    const operations:DesignOperation[]=Array.from(new Map(selected.map(({asset})=>[asset.id,{type:'add_asset_reference' as const,entry:{assetVersionId:asset.id,contentHash:asset.content_hash,purpose:'outline' as const,rightsVerified:true,geometryVerified:true}}])).values());
    const glyphPlacements=selected.map(({asset,u,v})=>({glyphAssetVersionId:asset.id,codepointText:asset.text,uMm:u,vMm:v,supplierProductVariantVersionId:asset.supplier_product_variant_version_id??null}));
    if(inscription.phase==='existing'){if(!evidenceId)throw new Error('Für geschützten Bestand einen eigenen Prüf- und Zuordnungsnachweis auswählen.');operations.push({type:'set_inscription_originals',elementId:inscription.id,glyphPlacements,evidenceVersionId:evidenceId});}
    else operations.push({type:'set_inscription_layout',elementId:inscription.id,glyphPlacements,renderingBasis:'verified_contours'});
    onsubmit(operations);onclose();
  }catch(problem){error=(problem as Error).message;}}
</script>
<dialog bind:this={dialog} oncancel={onclose} aria-labelledby="glyph-layout-title">
  <form onsubmit={commit}>
    <header><div><span>BELEGTE ORIGINALDATEN</span><h2 id="glyph-layout-title">Zeichen präzise zuordnen.</h2></div><button class="close" type="button" onclick={onclose} aria-label="Schließen">×</button></header>
    <div class="body"><p>Wählen Sie die fachlich freigegebenen Originalkonturen dieser Herstellerschrift und ihre einzeln geprüften Positionen auf der Schriftfläche.</p><pre>{inscription.exactText}</pre><p class="hint">Gewünschte Hersteller-Nennschrifthöhe: {requested??'noch offen'} mm. Tatsächliche Konturhöhen von Groß- und Kleinbuchstaben dürfen verschieden sein.</p>
      {#if !available.length}<div class="empty"><strong>Noch keine passenden Originalzeichen.</strong><p>Originalkontur, konkrete Herstellergröße und Nutzungsrechte zuerst in der Zeichenbibliothek prüfen. Die Bildreferenz bleibt bis dahin als solche gekennzeichnet.</p><a href="/glyph-library">Zeichenbibliothek öffnen</a></div>{/if}
      {#each entries as entry,index}<div class="glyph-row"><label>Original {index+1}<select use:searchableSelect={entry.assetId} bind:value={entry.assetId} required><option value="">Original auswählen</option>{#each available as asset}<option value={asset.id}>{asset.text} · {asset.nominal_font_height_mm??'?'} mm Nennschrift · Kontur {asset.width_mm} × {asset.height_mm} mm</option>{/each}</select></label><label>u (mm)<input bind:value={entry.u} inputmode="decimal" required placeholder="Belegter Wert"/></label><label>v (mm)<input bind:value={entry.v} inputmode="decimal" required placeholder="Belegter Wert"/></label><button class="remove" type="button" onclick={()=>entries=entries.filter((_,i)=>i!==index)} aria-label={`Original ${index+1} entfernen`}>×</button></div>{/each}
      <button class="btn small" type="button" disabled={!available.length} onclick={()=>entries=[...entries,{assetId:'',u:'',v:''}]}>Originalposition ergänzen</button>
      {#if inscription.phase==='existing'}<label class="evidence">Prüfnachweis für den geschützten Bestand<select use:searchableSelect={evidenceId} bind:value={evidenceId} required><option value="">Eigene Dokumentversion auswählen</option>{#each evidence as item}<option value={item.version_id??item.document_version_id??item.id}>{item.name??item.title??item.id}</option>{/each}</select></label><p class="hint">Der bestehende Wortlaut und seine Lage bleiben gesperrt. Die Zuordnung wird auf dem Server fachlich autorisiert.</p>{/if}
      {#if error}<p class="error" role="alert">{error}</p>{/if}
    </div><footer><button class="btn" type="button" onclick={onclose}>Abbrechen</button><button class="btn primary" type="submit" disabled={!available.length||!entries.length}>Geprüfte Konturen zuordnen</button></footer>
  </form>
</dialog>
<style>
dialog{padding:0;border:1px solid var(--line);border-radius:8px;width:min(850px,calc(100vw - 32px));max-height:90vh;color:var(--ink);background:var(--paper);box-shadow:0 20px 70px #172f2940}dialog::backdrop{background:#1b2b256b}header{display:flex;justify-content:space-between;align-items:flex-start;padding:28px 30px 20px;border-bottom:1px solid var(--line)}header span{font-size:10px;letter-spacing:.14em;color:var(--muted)}h2{font-size:25px;font-weight:500;margin:10px 0 0}.close,.remove{background:none;border:0;color:var(--muted);font-size:26px;cursor:pointer;min-height:44px;min-width:44px}.body{padding:24px 30px;max-height:60vh;overflow:auto}.body>p{font-size:13px;line-height:1.7;margin-top:0;max-width:680px}.body pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;font-size:17px;font-weight:500;line-height:1.65;background:var(--wash);padding:18px 22px;border-left:3px solid var(--forest)}.body .hint{font-size:12px;color:var(--muted);line-height:1.7}.empty{border:1px solid var(--line);background:var(--wash);padding:18px;margin:20px 0;font-size:13px;line-height:1.7}.empty a{color:var(--forest)}.glyph-row{display:grid;grid-template-columns:minmax(230px,1fr) 120px 120px 44px;gap:12px;align-items:end;padding:15px 0;border-bottom:1px solid var(--line)}.glyph-row label,.evidence{display:grid;gap:7px;font-size:13px;font-weight:500}.glyph-row input,.glyph-row select,.evidence select{font:inherit;font-weight:400;padding:10px;min-height:42px;width:100%;min-width:0;border:1px solid var(--line);border-radius:4px;background:var(--paper);color:inherit}.body>.btn{margin-top:18px}.evidence{margin-top:24px}.error{color:var(--danger);background:var(--danger-wash);padding:12px;font-size:12px;line-height:1.7}footer{padding:18px 30px;display:flex;justify-content:flex-end;gap:12px;background:var(--wash);border-top:1px solid var(--line)}@media(max-width:650px){.body,header,footer{padding:20px}.glyph-row{grid-template-columns:1fr 1fr 44px}.glyph-row label:first-child{grid-column:1/-1}.glyph-row input,.glyph-row select,.evidence select{font-size:16px;min-height:48px}footer{flex-wrap:wrap}h2{font-size:22px}}
</style>
